import{_ as a,o as t,c as r,a3 as s}from"./chunks/framework.BTt0kA_k.js";const o="/RelayPulse/screenshots/user/iq-participant.webp",i="/RelayPulse/screenshots/user/iq-setup.webp",f=JSON.parse('{"title":"智商测试","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/iq-test.md","filePath":"user/use/iq-test.md"}'),p={name:"user/use/iq-test.md"};function l(n,e,c,h,d,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="智商测试" tabindex="-1">智商测试 <a class="header-anchor" href="#智商测试" aria-label="Permalink to &quot;智商测试&quot;">​</a></h1><p>入口：<strong>测试 → 智商测试</strong>。使用同一组题目对比多个模型或推理强度，查看实际输出、调用耗时和 Token 用量。</p><p>这里的“成功”表示调用成功完成，不能直接视为答题正确。当前流程供你结合参考答案阅读、比较输出，不会自动给出智力分数或正确率排名。</p><h2 id="_1-准备题目和候选模型" tabindex="-1">1. 准备题目和候选模型 <a class="header-anchor" href="#_1-准备题目和候选模型" aria-label="Permalink to &quot;1. 准备题目和候选模型&quot;">​</a></h2><p>先在<a href="./questions.html">题库管理</a>中准备并启用题目；在“配置 → 站点管理”中配置站点并启用要使用的模型。</p><p>返回“智商测试”，在“题目选择”中搜索并勾选题目。跨页选择后可以查看已选数量；全选按钮作用于当前页可选题目。</p><h2 id="_2-添加测试参与者" tabindex="-1">2. 添加测试参与者 <a class="header-anchor" href="#_2-添加测试参与者" aria-label="Permalink to &quot;2. 添加测试参与者&quot;">​</a></h2><ol><li>点击“添加参与者”。</li><li>按站点选择启用的模型。</li><li>选择推理强度；需要时填写独立的手写请求参数。</li><li>检查“IQ 参数预览”，点击“添加参与者”。</li></ol><p>同一个模型可以添加多个推理强度组合。IQ 参数独立于日常探针配置，手写字段优先级高于推理强度预设。</p><p>可用档位取决于协议，服务商是否接受该档位仍需预检验证。不要在手写参数中覆盖 <code>model</code>、<code>stream</code>、<code>messages</code>、<code>input</code>、<code>prompt</code>、<code>system</code> 等系统保留字段。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/iq-participant.webp"><img src="'+o+'" alt="添加测试参与者，选择模型与推理强度，并检查 IQ 参数预览"></a></p><figcaption>① 选择模型及推理强度；② 检查实际 IQ 参数。图中使用本地演示模型。</figcaption></figure><h2 id="_3-等待参与者预检" tabindex="-1">3. 等待参与者预检 <a class="header-anchor" href="#_3-等待参与者预检" aria-label="Permalink to &quot;3. 等待参与者预检&quot;">​</a></h2><p>每个参与者添加后会自动检测其当前执行快照，状态为“检测中”“可用”或“不可用”。预检会发送真实请求，也可能产生费用。</p><p>所有参与者预检通过后才可开始。预检失败时，将鼠标移到状态上查看原因；检查配置后，使用“重新探测”读取最新配置并重新检测，或移除该参与者后重新添加。</p><p>参与者按快照执行。改变站点配置后，不应把旧的“可用”状态当作新配置已经通过验证。</p><h2 id="_4-设置重试并开始" tabindex="-1">4. 设置重试并开始 <a class="header-anchor" href="#_4-设置重试并开始" aria-label="Permalink to &quot;4. 设置重试并开始&quot;">​</a></h2><p>“失败重试”可填 <strong>0–20 次</strong>，默认 5 次，次数不含首次调用，只在请求报错时重试，不会因为答案不符合参考答案而重试。</p><p>开始前检查页面估算的请求数量：</p><p><strong>题目数 × 参与者数 = 首次调用次数。</strong></p><p>例如 3 道题、2 个参与者，基础调用为 6 次，预检和失败重试还会额外产生请求。确认后点击“开始测试”。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/iq-setup.webp"><img src="'+i+'" alt="智商测试开始前，选中两道题、两个预检可用的参与者，并设置失败重试"></a></p><figcaption>① 勾选题目并核对右侧参与者的预检状态；② 设置重试次数后开始。本例为 2 道题 × 2 个参与者，重试设为 0；默认重试次数仍为 5。</figcaption></figure><h2 id="_5-阅读运行看板" tabindex="-1">5. 阅读运行看板 <a class="header-anchor" href="#_5-阅读运行看板" aria-label="Permalink to &quot;5. 阅读运行看板&quot;">​</a></h2><p>运行中展示当前题目、整场进度、已结束调用数，以及各参与者的状态。题目按顺序执行，同一道题的多个参与者并行调用；某个调用失败不会直接终止后续题目。</p><p>调用结束后，点击“查看输出”或“查看详情”打开<a href="./iq-history.html">输出回放</a>。可以查看首 Token、总耗时、Token 用量，以及错误和重试尝试。</p><h2 id="中止测试" tabindex="-1">中止测试 <a class="header-anchor" href="#中止测试" aria-label="Permalink to &quot;中止测试&quot;">​</a></h2><p>点击“中止测试”并确认，会保留已经完成的结果，正在运行和尚未开始的调用标记为已中止。中止不能撤销已经发送给服务商的请求或已产生的用量。</p><p>整场结束后，在“测试 → 历史记录”查看本次运行。测试完成通知的设置见<a href="./notifications.html">消息通知</a>。</p>',27)])])}const m=a(p,[["render",l]]);export{f as __pageData,m as default};
